<?php declare(strict_types=1);
namespace Kulturhus\Native\Web\Communication;
use Kulturhus\Native\Web\{Html,Workspace};
use Kulturhus\Native\Communication\EditorialMonth;
use Kulturhus\Native\Language\{Catalog,EditorialHubMessages as Messages};
final class MonthPlanner extends Workspace
{
    private array $messages=[];
    private string $module='social';
    private const MONTHS=['Januar','Februar','März','April','Mai','Juni','Juli','August','September','Oktober','November','Dezember'];
    private function text(string $source,array $values=[]):string{return Messages::text($source,$this->messages,$values);}
    private function url(array $query=[]):string{return '/?'.http_build_query(['view'=>$this->module,'section'=>'planning','planning_view'=>'month']+$query);}
    public function render(array $input,string $module='social'):string
    {
        if(!in_array($module,['social','newsletter'],true))throw new \DomainException('Unbekannter Arbeitsbereich.',422);$this->access->require($module,'read');$this->module=$module;$this->messages=(new Catalog($this->db,$this->access))->messages();$t=fn($s,$v=[])=>Html::e($this->text($s,$v));
        $context=array_intersect_key($input,array_flip(['plan_month','plan_channel','plan_state','plan_step']));
        $h='<section class="social-planner" data-editorial-calendar aria-labelledby="social-plan-heading"><header class="social-plan-header"><h2 id="social-plan-heading">'.$t('Redaktionskalender').'</h2></header>';
        try{$result=(new EditorialMonth($this->db,$this->box()))->listing($this->access,$input);}catch(\DomainException $error){
            $status=in_array($error->getCode(),[403,409,422,503],true)?$error->getCode():422;if(in_array($error->getMessage(),['Für diese Aktion fehlt die Berechtigung.','Für diese Aktion fehlt die aktuelle Vereinsberechtigung.'],true))$status=403;http_response_code($status);
            $private=str_starts_with($error->getMessage(),'Privater Schlüssel');$h.='<p class="notice" role="alert">'.$t($private?'Planung derzeit nicht verfügbar.':$error->getMessage()).'</p>';
            if(!$private){$human=[];foreach(['plan_month'=>'Monat','plan_channel'=>'Kanal','plan_state'=>'Status','plan_step'=>'Schritt']as$key=>$label)if(array_key_exists($key,$input))$human[$this->text($label)]=$input[$key];if($human)$h.='<details open><summary>'.$t('Ursprüngliche Monatsangaben').'</summary><pre>'.Html::e(json_encode($human,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT|JSON_INVALID_UTF8_SUBSTITUTE)).'</pre></details>';}
            return$h.'<a class="btn btn-outline theme-secondary" data-nav href="'.Html::e($this->url()).'">'.$t('Planung zurücksetzen').'</a></section>';
        }
        $title=$this->text(self::MONTHS[(int)$result['first']->format('n')-1]).' '.$result['first']->format('Y');$filters=['plan_channel'=>$result['channel'],'plan_state'=>$result['state'],'plan_step'=>$result['step']];
        $h.='<div class="social-plan-toolbar"><nav class="social-plan-months" aria-label="'.$t('Monat').'">';foreach([-1=>'Vorheriger Monat',1=>'Nächster Monat']as$delta=>$label){$month=$result['first']->modify(($delta>0?'+':'').$delta.' month')->format('Y-m');if($month<'1900-01'||$month>'2199-12')continue;$h.='<a class="btn btn-outline theme-secondary" data-nav rel="'.($delta<0?'prev':'next').'" aria-label="'.$t($label).'" href="'.Html::e($this->url(['plan_month'=>$month]+$filters)).'">'.($delta<0?'←':'→').'</a>';}$h.='<a class="btn btn-outline theme-secondary" data-nav href="'.Html::e($this->url($filters)).'">'.$t('Aktueller Monat').'</a></nav><h3>'.$t($title).'</h3></div>';
        $channels=['all'=>'Alle'];if($result['modules']['social'])$channels+=['facebook'=>'Facebook','instagram'=>'Instagram','stadtlandfunk'=>'StadtLand.Funk'];if($result['modules']['newsletter'])$channels['newsletter']='Newsletter';$channels['local']='Lokale Vorbereitung';
        $steps=['all'=>'Alle','publication'=>'Veröffentlichung','local'=>'Lokale Vorbereitung','automation'=>'Automatische Vorbereitung'];$states=['all'=>'Alle','pending'=>'Geplant','processing'=>'Wird versendet','sent'=>'Versendet','uncertain'=>'Ergebnis prüfen','cancelled'=>'Gestoppt','ready'=>'Lokal vorbereitet','failed'=>'Fehlgeschlagen','enabled'=>'Vorbereitung geplant','paused'=>'Vorbereitung pausiert','prepared'=>'Vorbereitet','outdated'=>'Inhalt geändert · erneut prüfen'];if($result['modules']['newsletter'])$states['partial']='Teilweise versendet';
        $options=fn($values)=>array_map(fn($v)=>$this->text($v),$values);$filterLabels=[];foreach([[$result['channel'],$channels],[$result['step'],$steps],[$result['state'],$states]]as[$value,$labels])if($value!=='all')$filterLabels[]=$this->text($labels[$value]??'Status prüfen');
        $h.='<details class="social-plan-filter-options"><summary>'.$t('Filter').($filterLabels?' · '.Html::e(implode(' · ',$filterLabels)):'').'</summary><form method="get" class="social-plan-filters">'.Html::hidden('view',$module).Html::hidden('section','planning').Html::hidden('planning_view','month').Html::input('plan_month',$this->text('Monat'),$result['month'],'month','min="1900-01" max="2199-12" required').Html::select('plan_channel',$this->text('Kanal'),$options($channels),$result['channel']).Html::select('plan_step',$this->text('Schritt'),$options($steps),$result['step']).Html::select('plan_state',$this->text('Status'),$options($states),$result['state']).'<button class="btn btn-outline theme-secondary">'.$t('Anzeigen').'</button></form></details>';
        $monthRows=array_filter($result['rows'],static fn($r)=>str_starts_with($r['day'],$result['month']));$h.='<p class="social-plan-count">'.$t('{count} Einträge in {month}',['count'=>count($monthRows),'month'=>$title]).'</p><p class="hint">'.$t('Zeitangaben für Berlin. Freigabe oder Automatik stehen am jeweiligen Eintrag.').' <span class="social-plan-scroll-hint">'.$t('Auf dem Smartphone den Kalender seitlich verschieben.').'</span></p><label class="social-plan-previews"><input class="check" id="social-plan-previews" type="checkbox">'.$t('Vorschaubilder anzeigen').'</label>';
        if(!$monthRows)$h.='<p class="social-plan-empty">'.$t('Keine Aufträge in diesem Monat für diese Auswahl.').'</p>';
        $h.='<div class="social-plan-scroll" tabindex="0" role="region" aria-label="'.$t('Monatskalender').'" aria-describedby="social-plan-heading"><div class="social-plan-grid"><div class="social-plan-weekdays">';foreach(['Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag','Sonntag']as$day)$h.='<span>'.$t($day).'</span>';$h.='</div>';$byDay=[];foreach($result['rows']as$row)$byDay[$row['day']][]=$row;
        for($day=$result['start'];$day<$result['end'];$day=$day->modify('+1 day')){$date=$day->format('Y-m-d');$outside=!str_starts_with($date,$result['month']);$today=$date===$result['today'];$h.='<section class="social-plan-day'.($outside?' is-outside':'').($today?' is-today':'').'" aria-label="'.Html::e($date).'"><h4><time datetime="'.$date.'"'.($today?' aria-current="date"':'').'>'.Html::e($day->format($outside?'j.n.':'j')).'</time></h4>';foreach($byDay[$date]??[]as$row)$h.=$this->card($row,$result,$filters);$h.='</section>';}
        return$h.'</div></div></section>';
    }
    private function card(array $row,array $result,array $filters):string
    {
        $t=fn($s,$v=[])=>Html::e($this->text($s,$v));$newsletter=$row['module']==='newsletter';$automatic=in_array($row['transport'],['automation','newsletter_automation','event_preparation'],true);$local=in_array($row['transport'],['local','newsletter_local'],true);
        $platform=$newsletter?'Newsletter':implode(' + ',array_map(static fn($c)=>['facebook'=>'Facebook','instagram'=>'Instagram','stadtlandfunk'=>'StadtLand.Funk'][$c]??'Meta',$row['channels']));if($platform==='')$platform='Social Media';
        $state=match($row['status']){'pending'=>'Geplant','processing'=>$newsletter?'Wird versendet':'Wird veröffentlicht','sent'=>$newsletter?'Versendet':'Veröffentlicht','uncertain'=>'Ergebnis prüfen','cancelled'=>'Gestoppt','ready'=>'Lokal vorbereitet','failed'=>'Fehlgeschlagen','paused'=>'Vorbereitung pausiert','prepared'=>$row['needs_approval']?'Entwurf vorbereitet · Freigabe fehlt':'Vorbereitet','outdated'=>'Inhalt geändert · erneut prüfen','partial'=>'Teilweise versendet','enabled'=>$newsletter&&$row['phase']==='send'?($row['needs_approval']?'Versand vorgesehen · Freigabe erforderlich':'Versand vorgesehen'):'Vorbereitung geplant',default=>'Status prüfen'};
        if(!empty($row['automatic_story'])&&in_array($row['status'],['prepared','enabled','pending'],true))$state='Automatisch zum Termin';
        elseif(!$newsletter&&$row['status']==='enabled'&&!empty($row['needs_approval']))$state='Vorbereitung geplant · Freigabe fehlt';
        $kind=['post'=>'Beitrag','story'=>'Story','reel'=>'Reel','carousel'=>'Karussell','event'=>'Veranstaltung','video'=>'Video','newsletter'=>'Newsletter'][$row['kind']]??'Beitrag';$title=$row['title'];
        if($newsletter&&$automatic&&$title===''&&isset($row['period_key'])){$caption=$row['period_quarter']?'Quartalsnewsletter':'Monatsnewsletter';$key=$row['period_key'];$period=preg_match('/\Amonth-([0-9]{4})-([0-9]{2})\z/D',$key,$m)?$this->text(self::MONTHS[(int)$m[2]-1]).' '.$m[1]:(preg_match('/\Aquarter-([0-9]{4})-Q([1-4])\z/D',$key,$m)?'Q'.$m[2].' '.$m[1]:'');$title=$this->text($caption).($period!==''?' · '.$period:'');}
        if(is_string($row['target_item_id']??null)&&$row['target_item_id']!==''){
            $url='/?'.http_build_query(['view'=>$newsletter?'newsletter':'social','section'=>'compose','item'=>$row['target_item_id'],'plan_month'=>$result['month']]+$filters);$open=$newsletter?'Ausgabe öffnen':'Redaktion öffnen';
            if(!$newsletter)$url.=match($row['kind']){'story'=>'#social-image-editor','reel'=>'#social-media-workspace',default=>''};
        }elseif($newsletter&&isset($row['focus_job'])){
            $url='/?'.http_build_query(['view'=>'newsletter','section'=>'planning','planning_view'=>'history','newsletter_job'=>$row['focus_job'],'newsletter_kind'=>'campaign','plan_month'=>$result['month']]+$filters);$open='Versanddetails öffnen';
        }elseif($row['transport']==='event_preparation'){
            $url='/?'.http_build_query(['view'=>'social','section'=>'events','event_plan'=>$row['id'],'plan_month'=>$result['month']]);$open='Vorbereitung öffnen';
        }elseif($newsletter){$url='/?view=newsletter&section=planning&planning_view=automation';$open='Planung öffnen';}
        else{$url='/?'.http_build_query(['view'=>'social','section'=>'planning','planning_view'=>'history','queue_job'=>$row['id'],'plan_month'=>$result['month']]+$filters).'#job-'.$row['id'];$open='Originalauftrag öffnen';}
        $h='<a id="plan-'.Html::e($row['id']).'" data-nav class="social-plan-card channel-'.Html::e($row['channel']).' state-'.Html::e($row['status']).'" data-plan-job="'.Html::e($row['id']).'" data-plan-kind="'.Html::e($row['kind']).'" data-plan-step="'.Html::e($row['step']).'" data-plan-channel="'.Html::e($row['channel']).'" data-plan-module="'.$row['module'].'" href="'.Html::e($url).'" aria-label="'.$t($open).' · '.Html::e($title).'"><span class="social-plan-card-top"><time datetime="'.Html::e($row['datetime']).'" title="'.Html::e($row['time']).'">'.Html::e(substr($row['time'],0,5)).'</time><span class="social-plan-platform" title="'.$t($platform).'">'.$t($platform).'</span></span><span class="social-plan-content">';
        if($row['image_id']!==null)$h.='<img src="/social-image/'.Html::e($row['image_id']).'/thumb" alt="" loading="lazy" width="160" height="90">';
        $h.='<strong>'.($row['title_missing']?$t(!empty($row['unassigned'])?'Newsletterzustellungen prüfen':'Originalfassung nicht verfügbar'):Html::e($title)).'</strong></span><span class="social-plan-card-labels"><span class="social-plan-kind kind-'.Html::e($row['kind']).'">'.$t($kind).'</span>';
        if($automatic||$local)$h.='<span class="social-plan-step">'.$t($automatic?($newsletter&&$row['phase']==='send'?'Versand':'Automatische Vorbereitung'):'Lokale Vorbereitung').'</span>';$h.='<span class="social-plan-status">'.$t($state).'</span>';
        if($newsletter&&isset($row['counts']['sent_count']))$h.='<span class="social-plan-recipient-count">'.$t('{sent} von {count} versendet',['sent'=>$row['counts']['sent_count'],'count'=>$row['counts']['recipients']]).'</span>';
        return$h.'</span></a>';
    }
}
